[CmdletBinding()]
param(
    [ValidateSet('New', 'InPlace', 'Workspace')]
    [string]$Mode,
    [string]$ProjectDir,
    [string]$ProjectName,
    [string]$ExportJson,
    [string]$SmartExportRef,
    [string]$DdlFile,
    [string]$LandingTable,
    [string]$LogicalSchema,
    [string]$ContextCode,
    [string]$WorkUser,
    [string]$SetupScript,
    [switch]$RefreshKit,
    [switch]$NonInteractive,
    [switch]$SkipChecks,
    [switch]$Force,
    [switch]$DryRun,
    [switch]$Build,
    [string]$OutFile,
    [string]$WorkspaceDir,
    [string]$WsSource
)

$ErrorActionPreference = 'Stop'
$Version   = '2.9.0 (2026-10-28)'
$Today     = Get-Date -Format 'yyyy-MM-dd'
$Stamp     = Get-Date -Format 'yyyyMMddHHmmss'
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$ScriptDir = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }
$script:Report   = New-Object System.Collections.Generic.List[string]
$script:Python   = $null
$script:Problems = 0
$env:PYTHONIOENCODING = 'utf-8'   # python ของ scripts พิมพ์ภาษาไทยผ่าน pipe บน Windows ได้
$env:PYTHONUTF8 = '1'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }

# ---------------------------------------------------------------------------
# UI helpers (สไตล์เดียวกับ kit Setup.ps1)
# ---------------------------------------------------------------------------
$script:Line = '=' * 60
function Write-Banner {
    Write-Host $script:Line -ForegroundColor Cyan
    Write-Host ' 🚀 ODI Migration Factory' -ForegroundColor Cyan
    Write-Host $script:Line -ForegroundColor Cyan
    Write-Host "    Blendata (Spark SQL) -> ODI 14c / Oracle 19c  ·  setup_migrate v$Version" -ForegroundColor DarkGray
    Write-Host '    knowledge/ = ขั้นตอนหลัก · kit = gates / status / decisions · + Business Rules / Gap Analysis' -ForegroundColor DarkGray
}
function Write-Section([string]$t) { Write-Host ''; Write-Host $t -ForegroundColor Cyan; Write-Host ('-' * 60) -ForegroundColor DarkCyan }
function Write-Ok([string]$m)   { Write-Host "   ✅ $m" -ForegroundColor Green }
function Write-Warn([string]$m) { Write-Host "   ⚠️  $m" -ForegroundColor Yellow }
function Write-Fail([string]$m) { Write-Host "   ❌ $m" -ForegroundColor Red; $script:Problems++ }
function Write-Hint([string]$m) { Write-Host "   💡 $m" -ForegroundColor DarkYellow }
function Write-Info([string]$m) { Write-Host "   $m" -ForegroundColor Gray }
function Add-Report([string]$status, [string]$path) { $script:Report.Add(('{0,-9} {1}' -f $status, $path)) }

function Get-DisplayPath([string]$p) {
    # แสดง path แบบ relative ต่อโฟลเดอร์ที่รันอยู่ (ไม่เปิดเผย path เต็มของเครื่อง)
    if ([string]::IsNullOrWhiteSpace($p)) { return $p }
    try {
        $sep = [System.IO.Path]::DirectorySeparatorChar
        $cwd = (Get-Location).Path.TrimEnd('\', '/')
        $full = [System.IO.Path]::GetFullPath($p).TrimEnd('\', '/')
        if ($full -ieq $cwd) { return '.' }
        if ($full.StartsWith($cwd + $sep, [System.StringComparison]::OrdinalIgnoreCase)) { return ('.' + $sep + $full.Substring($cwd.Length + 1)) }
    } catch { }
    return $p
}

function Read-Value {
    param([string]$Prompt, [string]$Default, [string]$Example, [switch]$Required, [switch]$AllowEmpty, [string]$DefaultLabel)
    if ($NonInteractive) {
        if ($Required -and [string]::IsNullOrWhiteSpace($Default)) { throw "A value is required: $Prompt (-NonInteractive)" }
        return $Default
    }
    $text = "👉 $Prompt"
    if ($Example -and $Example -ne $Default) { $text += " (e.g., $Example)" }
    if ($DefaultLabel -and -not [string]::IsNullOrEmpty($Default)) { $text += " [$DefaultLabel]" }
    elseif (-not [string]::IsNullOrEmpty($Default)) { $text += " [$Default]" }
    elseif ($AllowEmpty) { $text += ' [Enter = skip]' }
    while ($true) {
        $raw = Read-Host $text
        if ([string]::IsNullOrWhiteSpace($raw)) {
            if ($Required -and [string]::IsNullOrWhiteSpace($Default)) { Write-Warn 'This field is required.'; continue }
            return $Default
        }
        if ($raw.Trim() -eq '-') { return '' }
        return $raw.Trim().Trim('"').Trim("'")
    }
}
function Read-Choice([string]$Prompt, [string[]]$Options, [string]$Default) {
    if ($NonInteractive) { return $Default }
    $opt = $Options -join '/'
    while ($true) {
        $raw = Read-Host "👉 $Prompt ($opt) [$Default]"
        if ([string]::IsNullOrWhiteSpace($raw)) { return $Default }
        $hit = $Options | Where-Object { $_ -ieq $raw.Trim() } | Select-Object -First 1
        if ($hit) { return $hit }
        Write-Warn "Please choose one of: $opt"
    }
}
function Read-YesNo([string]$Prompt, [bool]$Default) {
    $d = if ($Default) { 'y' } else { 'n' }
    return ((Read-Choice $Prompt @('y', 'n') $d) -eq 'y')
}

