$script:QShown = @{}
function Get-QHelp([string]$Prompt) { foreach ($x in $script:QHelp) { if ($Prompt -match $x.p) { return $x } }; return $null }
function Show-QHelp([string]$Prompt, [string]$Default, [bool]$Required, [bool]$AllowEmpty) {
    $h = Get-QHelp $Prompt
    Write-Host ('   ' + ('─' * 56)) -ForegroundColor DarkGray
    Write-Host "❓ $Prompt" -ForegroundColor White
    if ($h -and $h.what) { Write-Host "   คืออะไร     $($h.what)" -ForegroundColor Gray }
    if ($h -and $h.use) { Write-Host "   ใช้ทำอะไร    $($h.use)" -ForegroundColor Gray }
}
function Show-QMore([string]$Prompt, [int]$RecIdx) {
    $h = Get-QHelp $Prompt
    Write-Host '   ℹ️  อธิบายละเอียด' -ForegroundColor Cyan
    $parts = @()
    if ($h -and $h.more) { $parts = @($h.more) } elseif ($h) { $parts = @($h.what, $h.use) | Where-Object { $_ } }
    if ($parts.Count -eq 0) { $parts = @('ข้อนี้ไม่มีคำอธิบายเพิ่ม') }
    foreach ($x in $parts) { Write-Host "      $x" -ForegroundColor Gray }
    if ($RecIdx -gt 0) { Write-Host "      ถ้ายังไม่แน่ใจ: เลือก $RecIdx (ค่าที่แนะนำ)" -ForegroundColor Gray }
    else { Write-Host "      ถ้ายังไม่แน่ใจ: เลือกข้อ ยังไม่ทราบ" -ForegroundColor Gray }
}
function Read-Menu([string]$Prompt, $Entries, [int]$RecIdx, [string]$Skip, [switch]$AllowText, [switch]$AllowPath) {
    # Entries: @{ kind; value; label } · ตอบด้วยเลขเท่านั้น หรือพิมพ์คำตอบ / path (เมื่ออนุญาต)
    $h = Get-QHelp $Prompt
    Write-Host '   ตัวเลือก' -ForegroundColor Gray
    for ($i = 0; $i -lt $Entries.Count; $i++) {
        $tag = if (($i + 1) -eq $RecIdx) { '   ← แนะนำ' } else { '' }
        Write-Host ('     {0}  {1}{2}' -f ($i + 1), $Entries[$i].label, $tag) -ForegroundColor White
    }
    if ($RecIdx -gt 0) {
        $why = if ($h -and $h.rec) { " — $($h.rec)" } else { '' }
        Write-Host "   👉 แนะนำ     $RecIdx ($($Entries[$RecIdx - 1].label))$why" -ForegroundColor DarkYellow
    } elseif ($h -and $h.rec) { Write-Host "   👉 แนะนำ     $($h.rec)" -ForegroundColor DarkYellow }
    $sk = if ($h -and $h.skip) { $h.skip } elseif ($Skip) { $Skip } else { 'ข้อนี้ต้องตอบ' }
    if ($RecIdx -gt 0) {
        if ($sk -match '^(กด Enter|ใช้ค่าแนะนำ|ใช้ค่าในวงเล็บ|ใช้โฟลเดอร์ในวงเล็บ|ใช้ค่าที่ kit)') {
            $rest = if ($sk -match '\(([^()]+)\)\s*$') { " — $($Matches[1])" } else { '' }
            $sk = "กด Enter = เลือก $RecIdx (ค่าแนะนำ)$rest"
        }
        else { $sk = "กด Enter = เลือก $RecIdx · $sk" }
    }
    Write-Host "   ถ้าไม่ตอบ    $sk" -ForegroundColor Gray
    $hint = "พิมพ์เลข 1–$($Entries.Count)"
    if ($AllowText) { $hint += ' หรือพิมพ์คำตอบได้เลย' }
    if ($AllowPath) { $hint += ' หรือวาง path ของไฟล์ / โฟลเดอร์' }
    Write-Host "   วิธีตอบ      $hint · ? = อธิบายละเอียด" -ForegroundColor Gray
    if ($AllowText) { Write-Host "                (ถ้าคำตอบเป็นตัวเลข 1–$($Entries.Count) ให้เลือก 1 ก่อนแล้วค่อยพิมพ์)" -ForegroundColor DarkGray }
    while ($true) {
        $lbl = if ($RecIdx -gt 0) { " [Enter = $RecIdx]" } else { '' }
        $raw = Read-Host "👉 คำตอบ$lbl"
        $v = if ($null -eq $raw) { '' } else { $raw.Trim().Trim('"').Trim("'") }
        if ($v -eq '?') { Show-QMore $Prompt $RecIdx; continue }
        if ($v -eq '' -and $RecIdx -gt 0) { return $Entries[$RecIdx - 1] }
        if ($v -match '^\d+$' -and [int]$v -ge 1 -and [int]$v -le $Entries.Count) { return $Entries[[int]$v - 1] }
        if ($AllowPath -and $v -and (Test-Path -LiteralPath $v)) { return @{ kind = 'path'; value = (Resolve-Path -LiteralPath $v).Path } }
        if ($AllowText -and $v) { return @{ kind = 'text'; value = $v } }
        Write-Warn "ตอบได้: $hint"
    }
}
function Read-Choice([string]$Prompt, [string[]]$Options, [string]$Default) {
    if ($NonInteractive) { return $Default }
    Show-QHelp $Prompt $Default $true $false
    $entries = @()
    foreach ($o in $Options) {
        $lab = if ($script:OptLabel.ContainsKey($o)) { $script:OptLabel[$o] } elseif ($o -match '^\d+$') { "ตัวที่ $o ในรายการด้านบน" } else { $o }
        $entries += @{ kind = 'opt'; value = $o; label = $lab }
    }
    $hasOut = @($Options | Where-Object { $_ -in @('s', 'q', 'h') }).Count -gt 0
    $dLab = if ($script:OptLabel.ContainsKey($Default)) { $script:OptLabel[$Default] } else { $Default }
    if (-not $hasOut) { $entries += @{ kind = 'unknown'; value = $Default; label = "ยังไม่ทราบ — ใช้ค่าแนะนำ ($dLab) ไปก่อน แก้ทีหลังได้" } }
    $rec = [array]::IndexOf($Options, $Default) + 1
    $e = Read-Menu $Prompt $entries $rec 'ใช้ค่าแนะนำ'
    if ($e.kind -eq 'unknown') { Write-Info "ใช้ $Default ไปก่อน (แก้ทีหลังได้)" }
    return $e.value
}
function Read-ChoiceOrPath([string]$Prompt, [string[]]$Options, [string]$Default) {
    if ($NonInteractive) { return $Default }
    Show-QHelp $Prompt $Default $true $false
    $entries = @($Options | ForEach-Object { @{ kind = 'opt'; value = $_; label = $(if ($script:OptLabel.ContainsKey($_)) { $script:OptLabel[$_] } else { $_ }) } })
    $e = Read-Menu $Prompt $entries ([array]::IndexOf($Options, $Default) + 1) '' -AllowPath
    if ($e.kind -eq 'path') { return "path:$($e.value)" }
    return $e.value
}
function Read-YesNo([string]$Prompt, [bool]$Default) {
    $d = if ($Default) { 'y' } else { 'n' }
    return ((Read-Choice $Prompt @('y', 'n') $d) -eq 'y')
}
function Read-Value {
    param([string]$Prompt, [string]$Default, [string]$Example, [switch]$Required, [switch]$AllowEmpty, [string]$DefaultLabel)
    if ($NonInteractive) {
        if ($Required -and [string]::IsNullOrWhiteSpace($Default)) { throw "A value is required: $Prompt (-NonInteractive)" }
        return $Default
    }
    Show-QHelp $Prompt $Default ([bool]$Required) ([bool]$AllowEmpty)
    $entries = @(@{ kind = 'type'; value = $null; label = 'พิมพ์คำตอบเอง' + $(if ($Example) { " (เช่น $Example)" } else { '' }) })
    if (-not [string]::IsNullOrEmpty($Default)) { $entries += @{ kind = 'default'; value = $Default; label = "ใช้ค่านี้: $Default" } }
    if ($AllowEmpty -or -not $Required) { $unk = 'ยังไม่ทราบ — ข้ามไปก่อน' }
    elseif (-not [string]::IsNullOrEmpty($Default)) { $unk = "ยังไม่ทราบ — ใช้ $Default ไปก่อน แก้ทีหลังได้" }
    else { $unk = 'ยังไม่ทราบ — พักไว้ก่อน (ออกจาก setup แล้วรันใหม่เมื่อได้คำตอบ)' }
    $entries += @{ kind = 'unknown'; value = $null; label = $unk }
    $rec = if (-not [string]::IsNullOrEmpty($Default)) { 2 } elseif ($AllowEmpty) { 2 } else { 0 }
    $skip = if ($AllowEmpty -or -not $Required) { 'ข้ามได้' } else { 'ข้อนี้ต้องตอบ' }
    while ($true) {
        $e = Read-Menu $Prompt $entries $rec $skip -AllowText
        switch ($e.kind) {
            'text' { if ($e.value -eq '-') { return '' }; return $e.value }
            'default' { return $Default }
            'unknown' {
                if ($AllowEmpty -or -not $Required) { Write-Info 'ข้ามไปก่อน'; return '' }
                if (-not [string]::IsNullOrEmpty($Default)) { Write-Info "ใช้ $Default ไปก่อน (แก้ทีหลังได้)"; return $Default }
                Write-Warn "พักไว้ก่อน — เตรียมคำตอบข้อ '$Prompt' (พิมพ์ ? ในข้อนั้นเพื่อดูว่าหาได้ที่ไหน) แล้วรัน setup_migrate.ps1 อีกครั้ง"
                exit 3
            }
            'type' {
                $t = Read-Host '   พิมพ์คำตอบ (Enter = กลับไปเลือกใหม่)'
                if (-not [string]::IsNullOrWhiteSpace($t)) { return $t.Trim().Trim('"').Trim("'") }
            }
        }
    }
}


# ---------------------------------------------------------------------------
# File / python helpers
# ---------------------------------------------------------------------------
function Get-Prop($obj, [string]$path, $default = '') {
    $cur = $obj
    foreach ($p in $path.Split('.')) {
        if ($null -eq $cur) { return $default }
        $prop = $cur.PSObject.Properties[$p]
        if ($null -eq $prop) { return $default }
        $cur = $prop.Value
    }
    if ($null -eq $cur -or ($cur -is [string] -and $cur -eq '')) { return $default }
    return $cur
}

function Resolve-Full([string]$p) {
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    return [System.IO.Path]::GetFullPath($(if ([System.IO.Path]::IsPathRooted($p)) { $p } else { Join-Path (Get-Location).Path $p }))
}

function Read-Text([string]$path) { return [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8) }

function Save-Text([string]$path, [string]$text) {
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllText($path, $text, $Utf8NoBom)
}

function Backup-File([string]$path) {
    $bak = "$path.bak-$Stamp"
    Copy-Item -LiteralPath $path -Destination $bak
    return $bak
}

# เขียนไฟล์ใหม่ของ overlay: มีอยู่แล้ว = ข้าม (หรือ -Force = backup แล้วเขียนทับ)
function Install-ProjectFile([string]$rel, [string]$content) {
    $full = Join-Path $script:Root $rel
    if (Test-Path $full) {
        if (-not $Force) { Add-Report 'skip' "$rel (มีอยู่แล้ว)"; return }
        if ($DryRun) { Add-Report 'dry-run' "$rel (backup + เขียนทับ)"; return }
        $null = Backup-File $full
        Save-Text $full $content
        Add-Report 'replace' "$rel (backup .bak-$Stamp)"
        return
    }
    if ($DryRun) { Add-Report 'dry-run' "$rel (สร้างใหม่)"; return }
    Save-Text $full $content
    Add-Report 'create' $rel
}

# patch ไฟล์เดิม: $Marker มีอยู่แล้ว = ข้าม · $Transform คืนข้อความใหม่ (หรือ $null = ไม่เปลี่ยน)
function Update-ProjectFile([string]$rel, [string]$Marker, [scriptblock]$Transform) {
    $full = Join-Path $script:Root $rel
    if (-not (Test-Path $full)) { Add-Report 'missing' "$rel (ไม่มีไฟล์ — ข้าม patch)"; return }
    $text = Read-Text $full
    if ($Marker -and $text.Contains($Marker)) { Add-Report 'skip' "$rel (patch แล้ว)"; return }
    $new = & $Transform $text
    if ($null -eq $new -or $new -eq $text) { Add-Report 'warn' "$rel (หาตำแหน่ง patch ไม่เจอ — แก้มือ)"; return }
    if ($DryRun) { Add-Report 'dry-run' "$rel (patch)"; return }
    Save-Text $full $new
    Add-Report 'patch' $rel
}

function Find-Python {
    $ErrorActionPreference = 'Continue'
    $candidates = @(@('py', '-3'), @('python'), @('python3'))
    foreach ($c in $candidates) {
        $exe = $c[0]
        if (-not (Get-Command $exe -ErrorAction SilentlyContinue)) { continue }
        $pre = @(); if ($c.Count -gt 1) { $pre = @($c[1..($c.Count - 1)]) }
        try {
            $v = & $exe @pre -c "import sys;print('%d.%d' % sys.version_info[:2])" 2>$null
            if ($LASTEXITCODE -eq 0 -and $v -match '^(\d+)\.(\d+)$') {
                if ([int]$Matches[1] -gt 3 -or ([int]$Matches[1] -eq 3 -and [int]$Matches[2] -ge 9)) {
                    return [pscustomobject]@{ Exe = $exe; Pre = $pre; Version = $v.Trim() }
                }
            }
        } catch { }
    }
    return $null
}

function Invoke-Py([string[]]$PyArgs) {
    # PS 5.1: stderr ของ native command + EAP Stop = throw → ใช้ Continue เฉพาะในนี้
    $ErrorActionPreference = 'Continue'
    $all = @($script:Python.Pre) + $PyArgs
    $prevEnc = [Console]::OutputEncoding
    try {
        try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }
        $out = & $script:Python.Exe @all 2>&1 | ForEach-Object { "$_" }
        $code = $LASTEXITCODE
    } finally { try { [Console]::OutputEncoding = $prevEnc } catch { } }
    return [pscustomobject]@{ Code = $code; Out = ($out -join "`n") }
}

# ---------------------------------------------------------------------------
# Payload (kit Setup.ps1) — ฝังท้ายไฟล์โดย -Build · แตกไป %TEMP% ตอนใช้
# ---------------------------------------------------------------------------
function Test-Payload([string]$Dir) {
    return (Test-Path (Join-Path $Dir 'kit/Setup.ps1'))
}
function Expand-Payload {
    $self = $PSCommandPath
    if (-not $self) { $self = $MyInvocation.ScriptName }
    if (-not $self -or -not (Test-Path $self)) { return $null }
    $text = [System.IO.File]::ReadAllText($self)
    $m = [regex]::Match($text, '(?s)#PAYLOAD-SHA (\w+)\s*\r?\n#PAYLOAD-BEGIN\r?\n(.*?)\r?\n#PAYLOAD-END')
    if (-not $m.Success) { return $null }
    $sha = $m.Groups[1].Value
    $dir = Join-Path ([System.IO.Path]::GetTempPath()) ('odi-migrate-' + $sha.Substring(0, 12))
    # ตรวจของใน cache จริงก่อนใช้ (บทเรียน K2 ของ kit: .complete อย่างเดียวเชื่อไม่ได้)
    if ((Test-Path (Join-Path $dir '.complete')) -and (Test-Payload $dir)) { return $dir }
    if (Test-Path $dir) { Remove-Item -LiteralPath $dir -Recurse -Force }
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
    $zip = Join-Path $dir 'payload.zip'
    $b64 = ($m.Groups[2].Value -replace '[#\s]', '')
    [System.IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String($b64))
    Expand-Archive -LiteralPath $zip -DestinationPath $dir -Force
    Remove-Item -LiteralPath $zip -Force
    if (-not (Test-Payload $dir)) { throw "payload ไม่ครบหลังแตกไฟล์ที่ $dir — ไฟล์ setup_migrate.ps1 อาจเสีย (สร้างใหม่ด้วย -Build)" }
    Set-Content -LiteralPath (Join-Path $dir '.complete') -Value $sha
    return $dir
}
function Invoke-Build {
    # สร้างไฟล์เดียว: โค้ดของไฟล์นี้ (ตัด payload เดิม) + zip(kit/Setup.ps1) แบบ base64
    if (-not $SetupScript -or -not (Test-Path $SetupScript)) { throw '-Build ต้องมี -SetupScript <kit Setup.ps1 / Setup11_fixed.ps1>' }
    $out = if ($OutFile) { Resolve-Full $OutFile } else { Join-Path $ScriptDir 'setup_migrate.ps1' }
    $stage = Join-Path ([System.IO.Path]::GetTempPath()) ('odi-build-' + $Stamp)
    New-Item -ItemType Directory -Path (Join-Path $stage 'kit') -Force | Out-Null
    Copy-Item -LiteralPath $SetupScript -Destination (Join-Path $stage 'kit/Setup.ps1')
    $wsSrc = if ($WsSource) { Resolve-Full $WsSource } else { $pd = Expand-Payload; if ($pd) { Join-Path $pd 'ws' } else { $null } }
    if ($wsSrc -and (Test-Path (Join-Path $wsSrc 'tools/workspace.py'))) { Copy-Item -LiteralPath $wsSrc -Destination (Join-Path $stage 'ws') -Recurse -Force }
    else { Write-Warn 'ไม่มีไฟล์ workspace (ws/) — -Mode Workspace จะใช้ไม่ได้ (ใส่ -WsSource <โฟลเดอร์ ws>)' }
    $zip = Join-Path ([System.IO.Path]::GetTempPath()) ('odi-build-' + $Stamp + '.zip')
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    if (Test-Path $zip) { Remove-Item -LiteralPath $zip -Force }
    [System.IO.Compression.ZipFile]::CreateFromDirectory($stage, $zip)   # รวมไฟล์ซ่อน (.claude/) ด้วย
    $bytes = [System.IO.File]::ReadAllBytes($zip)
    $sha = (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLower()
    $b64 = [Convert]::ToBase64String($bytes)
    $sb = New-Object System.Text.StringBuilder
    for ($i = 0; $i -lt $b64.Length; $i += 120) { [void]$sb.Append('#').Append($b64.Substring($i, [Math]::Min(120, $b64.Length - $i))).Append("`r`n") }
    $self = [System.IO.File]::ReadAllText($PSCommandPath)
    $cut = $self.IndexOf("`n#PAYLOAD-SHA ")
    if ($cut -ge 0) { $self = $self.Substring(0, $cut + 1) }
    $self = $self.TrimEnd() + "`r`n`r`n#PAYLOAD-SHA $sha`r`n#PAYLOAD-BEGIN`r`n" + $sb.ToString() + "#PAYLOAD-END`r`n"
    if ((Test-Path $out) -and ((Resolve-Full $out) -eq (Resolve-Full $PSCommandPath))) { Copy-Item -LiteralPath $out -Destination "$out.bak-$Stamp" }
    [System.IO.File]::WriteAllText($out, $self, (New-Object System.Text.UTF8Encoding($true)))   # with BOM
    Remove-Item -LiteralPath $stage -Recurse -Force; Remove-Item -LiteralPath $zip -Force
    $kitV = if ((Get-Content -LiteralPath $SetupScript -TotalCount 60 -Encoding UTF8) -join "`n" -match 'Version\s*:\s*([0-9.]+)') { $Matches[1] } else { '?' }
    Write-Ok "สร้าง $out ($([Math]::Round((Get-Item $out).Length / 1KB)) KB) · payload sha $($sha.Substring(0, 12)) · kit $kitV"
}

