function Row([string]$n, [string]$topic, [string]$ans, [string]$src) {
    $st = if ([string]::IsNullOrWhiteSpace($ans)) { '⬜' } else { '✅' }
    if ([string]::IsNullOrWhiteSpace($ans)) { $ans = '_(ถาม SA)_' }
    return "| $n | $topic | $ans | $src | $st |"
}
$rows = @(
    (Row 'I1'  'โฟลเดอร์งาน Blendata ต้นทาง' $(if ($export) { "``$export``" } else { '' }) 'config `paths.input_export_workflow`'),
    ('| I2 | ไฟล์ reference SmartExport จาก repository ปลายทาง | ' + $(if ($refFiles.Count) { ($refFiles | ForEach-Object { "``input/odi_reference/$($_.Name)``" }) -join ', ' } else { "field template ``$(Get-Prop $cfg 'odi.field_template' 'references/odi-export-field-template.json')`` (ODI $(Get-Prop $cfg 'odi.odi_version' '?'), repo $(Get-Prop $cfg 'odi.repository_version' '?')) · ยังไม่มี Smart Export หลัง import" }) + ' | config `odi.*`, `input/odi_reference/` | ' + $(if ($refFiles.Count) { '✅' } else { '⚠️' }) + ' |'),
    ('| I3 | โครงสร้างคอลัมน์ตารางปลายทาง (DDL) | ' + $(if ($ddlFiles.Count) { ($ddlFiles | ForEach-Object { "``input/oracle_ddl/$($_.Name)``" }) -join ', ' } else { '_(วาง DDL หรือ CSV ของ `all_tab_columns` ที่ `input/oracle_ddl/` — ใช้กับ `check_sql.py --ddl`)_' }) + ' | `input/oracle_ddl/`, rp00 P3 | ' + $(if ($ddlFiles.Count) { '✅' } else { '⬜' }) + ' |'),
    ('| I4 | Oracle schema และวิธี qualify | schema / user / prefix อ่านจาก Smart Export แล้ว: `' + (Get-Prop $cfg 'odi.work_user' '?') + '` / `' + (Get-Prop $cfg 'target_table_prefix' '') + '` · ถามเฉพาะวิธี qualify → Q "Schema qualification" ใน `status/OPEN_DECISIONS.md` | config `odi.*` (จาก Smart Export) | ⬜ |'),
    (Row 'I5'  'ODI ProjectName' $(Get-Prop $cfg 'odi.project_name' '') 'config `odi.project_name`'),
    (Row 'I6'  'ProjectCode / prefix เดิมที่ต้อง rename' $(Get-Prop $cfg 'odi.project_code' '') 'config `odi.project_code`'),
    (Row 'I7'  'FolderName' $(Get-Prop $cfg 'odi.folder_name' '') 'config `odi.folder_name`'),
